const VOO_MAP = new Map<string, number>(VOO_HISTORICAL_SERIES);

const FIRST_DATE = VOO_HISTORICAL_SERIES[0][0];
const LAST_DATE = VOO_HISTORICAL_SERIES[VOO_HISTORICAL_SERIES.length - 1][0];
const FIRST_PRICE = VOO_HISTORICAL_SERIES[0][1];
const LAST_PRICE = VOO_HISTORICAL_SERIES[VOO_HISTORICAL_SERIES.length - 1][1];

/**
 * Fast O(1) retrieval of daily VOO total-return benchmark price with boundary clamping.
 */
export function getVooPrice(date: string): number {
  const price = VOO_MAP.get(date);
  if (price !== undefined) return price;
  if (date <= FIRST_DATE) return FIRST_PRICE;
  if (date >= LAST_DATE) return LAST_PRICE;
  return FIRST_PRICE;
}
